def inorder_traversal(nodes: list) -> list[int]:
    if not nodes or nodes[0] is None:
        return []
    res = []
    def dfs(idx):
        if idx >= len(nodes) or nodes[idx] is None:
            return
        dfs(2 * idx + 1)
        res.append(nodes[idx])
        dfs(2 * idx + 2)
    dfs(0)
    return res
